style.css:
@-moz-document domain("roblox.com") {
/* ── BACKGROUND ── */
  body,
  #react-app,
  .rbx-body {
    background: #000 url("https://media1.tenor.com/m/7WWo-1JTqk8AAAAd/king-von-piracy.gif")
      center center / cover fixed !important;
  }

  /* Darken fixed page wrappers so the GIF shows through */
  .ng-scope,
  #main-game-page-container,
  .game-card-container,
  .container-main,
  .rbx-page-content {
    background: transparent !important;
  }

  /* ── NAVBAR ── */
  #navigation-bar,
  #navigation-header,
  .rbx-navbar,
  .header-top {
    background: rgba(0, 0, 0, 0.75) !important;
    backdrop-filter: blur(6px) !important;
    border-bottom: 1px solid rgba(255, 30, 30, 0.6) !important;
  }

  /* ── SIDEBAR / LEFT NAV ── */
  #left-col,
  .sidebar,
  .rbx-left-col {
    background: rgba(0, 0, 0, 0.65) !important;
    backdrop-filter: blur(4px) !important;
    border-right: 1px solid rgba(200, 0, 0, 0.4) !important;
  }

  /* ── CARDS & PANELS ── */
  .card,
  .section-content,
  .game-card,
  .hlist,
  .rbx-container-col,
  .stack-list,
  .item-card,
  .avatar-card,
  [class*="Card"],
  [class*="card"],
  .game-carousel,
  .section {
    background: rgba(10, 0, 0, 0.72) !important;
    border: 1px solid rgba(180, 0, 0, 0.35) !important;
    backdrop-filter: blur(3px) !important;
    border-radius: 6px !important;
  }

  /* ── BUTTONS ── */
  .btn-primary-md,
  .btn-growth-md,
  .btn-common-play-game-lg,
  .btn-growth-lg,
  .PurchaseButton,
  [class*="btn-primary"] {
    background: #8b0000 !important;
    border-color: #ff2020 !important;
    color: #fff !important;
    text-shadow: 0 0 6px #ff0000 !important;
    transition: all 0.2s ease !important;
  }

  .btn-primary-md:hover,
  .btn-growth-md:hover,
  .btn-common-play-game-lg:hover,
  [class*="btn-primary"]:hover {
    background: #ff1a1a !important;
    box-shadow: 0 0 12px #ff0000 !important;
  }

  /* ── TEXT ── */
  body,
  .text-lead,
  .text-name,
  h1, h2, h3, h4, h5, h6,
  .font-header-1,
  .font-header-2,
  p, span, a, label {
    color: #f0f0f0 !important;
  }

  a:hover {
    color: #ff4444 !important;
  }

  /* ── INPUTS ── */
  input,
  textarea,
  select,
  .form-control {
    background: rgba(20, 0, 0, 0.8) !important;
    border: 1px solid rgba(255, 30, 30, 0.5) !important;
    color: #fff !important;
    border-radius: 4px !important;
  }

  input:focus,
  textarea:focus,
  select:focus,
  .form-control:focus {
    border-color: #ff2020 !important;
    box-shadow: 0 0 8px rgba(255, 0, 0, 0.5) !important;
    outline: none !important;
  }

  /* ── FOOTER ── */
  #footer,
  .footer-container {
    background: rgba(0, 0, 0, 0.85) !important;
    border-top: 1px solid rgba(200, 0, 0, 0.4) !important;
    color: #aaa !important;
  }

  /* ── SCROLLBAR ── */
  ::-webkit-scrollbar {
    width: 8px;
    background: #0a0000;
  }
  ::-webkit-scrollbar-thumb {
    background: #8b0000;
    border-radius: 4px;
  }
  ::-webkit-scrollbar-thumb:hover {
    background: #ff2020;
  }

  /* ── RED GLOW VIGNETTE ── */
  body::before {
    content: "";
    position: fixed;
    inset: 0;
    pointer-events: none;
    z-index: 0;
    background: radial-gradient(
      ellipse at center,
      transparent 40%,
      rgba(180, 0, 0, 0.35) 100%
    );
  }
}
